/** What a stored configuration looks like in the form. */
export function toFormValues(spec: ChannelSpec, stored: Record<string, unknown> | undefined): FieldValues {
  const values: FieldValues = { ...spec.defaults }
  for (const field of spec.fields) {
    const value = stored?.[field.key]
    if (value === undefined || value === null) continue
    if (field.kind === 'checkbox') values[field.key] = value === true || value === 'true'
    else if (field.kind === 'json') values[field.key] = JSON.stringify(value, null, 2)
    else values[field.key] = String(value)
  }
  return values
}

/**
 * The settings to save: keys the form does not manage kept as stored, the form's own replaced;
 * empty fields and hidden ones left out. Throws with a readable message if the JSON is not valid.
 */
export function toSettings(spec: ChannelSpec, values: FieldValues, stored: Record<string, unknown> | undefined) {
  const managed = new Set(spec.fields.map((field) => field.key))
  const settings: Record<string, unknown> = Object.fromEntries(
    Object.entries(stored ?? {}).filter(([key]) => !managed.has(key)),
  )
  for (const field of spec.fields) {
    if (field.when && !field.when(values)) continue
    const value = values[field.key]
    if (field.kind === 'checkbox') {
      settings[field.key] = value === true
      continue
    }
    const text = typeof value === 'string' ? value.trim() : ''
    if (!text) continue
    if (field.kind === 'number') {
      const number = Number(text)
      if (!Number.isFinite(number)) throw new Error(`${field.label} must be a number`)
      settings[field.key] = number
    } else if (field.kind === 'json') {
      let parsed: unknown
      try {
        parsed = JSON.parse(text)
      } catch {
        throw new Error(`${field.label}: not valid JSON`)
      }
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        throw new Error(`${field.label} must be a JSON object`)
      }
      settings[field.key] = parsed
    } else {
      settings[field.key] = text
    }
  }
  return settings
}

'use client'

import { useState } from 'react'
import { Send } from 'lucide-react'
import type { ChannelStatus, NotificationChannels } from '@babulvaibhav/egradx-client'
import { useAction } from '@babulvaibhav/egradx-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Checkbox } from '@/components/ui/checkbox'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Textarea } from '@/components/ui/textarea'
import { ConfirmDialog } from '../egradx-common'
import { errorText, formatRelative, ignoreNotice, tone, type Notify } from '../egradx-ui'
import { toFormValues, toSettings, type ChannelSpec, type Field, type FieldValues } from './channel-forms'

interface ChannelCardProps {
  spec: ChannelSpec
  /** Undefined when the server does not have this channel. */
  status: ChannelStatus | undefined
  /** The page's channel list: each change reloads it, and with it this card. */
  actions: Pick<NotificationChannels, 'save' | 'remove' | 'clearSecret' | 'test'>
  canManage: boolean
  defaultTestAddress?: string
  onNotify?: Notify
}

/** One channel's settings: status, fields, write-only secret, save, remove and a test message. */
export function ChannelCard({ spec, status, actions, canManage, defaultTestAddress, onNotify = ignoreNotice }: ChannelCardProps) {
  const stored = status?.configuration ?? null
  const [values, setValues] = useState<FieldValues>(() => toFormValues(spec, stored?.settings))
  const [enabled, setEnabled] = useState(stored?.enabled ?? true)
  const [secret, setSecret] = useState('')
  const [formError, setFormError] = useState<string | null>(null)
  const [testAddress, setTestAddress] = useState(spec.id === 'email' ? (defaultTestAddress ?? '') : '')
  const [confirmRemove, setConfirmRemove] = useState(false)

  const save = useAction(async () => {
    await actions.save(spec.id, { enabled, settings: toSettings(spec, values, stored?.settings), ...(secret ? { secret } : {}) })
    setSecret('')
    onNotify({ tone: 'success', title: `${spec.label} settings saved` })
  })
  const remove = useAction(async () => {
    await actions.remove(spec.id)
    setConfirmRemove(false)
    onNotify({ tone: 'success', title: `${spec.label} settings removed` })
  })
  const clearSecret = useAction(() => actions.clearSecret(spec.id))
  const test = useAction(async () => {
    try {
      await actions.test(spec.id, testAddress.trim())
      onNotify({ tone: 'success', title: 'Test queued', description: 'Its result appears in the delivery log in a few seconds.' })
    } catch (error) {
      onNotify({ tone: 'error', title: 'Test not sent', description: errorText(error) })
    }
  })

  const submit = () => {
    setFormError(null)
    const missing = spec.fields.find((field) => field.required && (!field.when || field.when(values)) && !String(values[field.key] ?? '').trim())
    if (missing) return setFormError(`${missing.label} is required`)
    try {
      toSettings(spec, values, stored?.settings)
    } catch (error) {
      return setFormError((error as Error).message)
    }
    void save.run().catch(() => {})
  }

  if (!status) {
    return (
      <Card className="opacity-70">
        <CardHeader>
          <CardTitle>{spec.label}</CardTitle>
          <CardDescription>Not installed on this server.</CardDescription>
        </CardHeader>
      </Card>
    )
  }

  const shownFields = spec.fields.filter((field) => !field.when || field.when(values))
  const error = formError ?? (save.error ? errorText(save.error) : remove.error ? errorText(remove.error) : null)

  return (
    <Card>
      <CardHeader>
        <CardTitle>{spec.label}</CardTitle>
        <CardDescription>
          {status.available ? null : <span className="text-foreground block">{status.unavailableReason}</span>}
          {stored
            ? `This organization's settings, saved ${formatRelative(stored.updatedAt)}.`
            : status.available
              ? 'Using the settings shared by all organizations.'
              : 'Not configured.'}
        </CardDescription>
        <CardAction>
          <Badge variant="outline" className={status.available ? tone.success : tone.warning}>
            {status.available ? 'Available' : 'Unavailable'}
          </Badge>
        </CardAction>
      </CardHeader>
      <CardContent className="space-y-4">
        <label className="flex items-start gap-2 text-sm">
          <Checkbox checked={enabled} disabled={!canManage} onCheckedChange={(checked) => setEnabled(checked === true)} />
          <span>
            Enabled
            <span className="text-muted-foreground block text-xs">
              Off means this organization never sends on {spec.label}; it does not fall back to the shared settings.
            </span>
          </span>
        </label>

        <div className="grid gap-4 sm:grid-cols-2">
          {shownFields.map((field) => (
            <FieldInput
              key={field.key}
              id={`${spec.id}-${field.key}`}
              field={field}
              value={values[field.key]}
              disabled={!canManage}
              onChange={(value) => setValues((previous) => ({ ...previous, [field.key]: value }))}
            />
          ))}
          <div className="space-y-1.5">
            <Label htmlFor={`${spec.id}-secret`}>{spec.secretLabel}</Label>
            <Input
              id={`${spec.id}-secret`}
              type="password"
              autoComplete="new-password"
              disabled={!canManage}
              placeholder={stored?.hasSecret ? 'Stored — leave blank to keep' : ''}
              value={secret}
              onChange={(event) => setSecret(event.target.value)}
            />
            {stored?.hasSecret && canManage && (
              <button
                type="button"
                className="text-muted-foreground text-xs underline"
                onClick={() => void clearSecret.run().catch(() => {})}
                disabled={clearSecret.pending}
              >
                Remove stored secret
              </button>
            )}
          </div>
        </div>

        {error && (
          <p className="text-destructive text-sm" role="alert">
            {error}
          </p>
        )}
      </CardContent>
      {canManage && (
        <CardFooter className="flex-col items-stretch gap-3">
          <div className="flex flex-wrap justify-end gap-2">
            {stored && (
              <Button variant="outline" onClick={() => setConfirmRemove(true)}>
                Remove settings
              </Button>
            )}
            <Button onClick={submit} disabled={save.pending}>
              {save.pending ? 'Saving…' : 'Save'}
            </Button>
          </div>
          <div className="flex flex-wrap items-end gap-2 border-t pt-3">
            <div className="min-w-48 flex-1 space-y-1.5">
              <Label htmlFor={`${spec.id}-test`}>Send a test to</Label>
              <Input id={`${spec.id}-test`} placeholder={spec.testPlaceholder} value={testAddress} onChange={(event) => setTestAddress(event.target.value)} />
              <p className="text-muted-foreground text-xs">{spec.testHelp}</p>
            </div>
            <Button
              variant="outline"
              onClick={() => void test.run()}
              disabled={!status.available || !testAddress.trim() || test.pending}
              title={status.available ? undefined : (status.unavailableReason ?? undefined)}
            >
              <Send /> Send test
            </Button>
          </div>
        </CardFooter>
      )}
      <ConfirmDialog
        open={confirmRemove}
        onOpenChange={setConfirmRemove}
        title={`Remove ${spec.label} settings?`}
        description="This organization then uses the settings shared by all organizations, if there are any."
        confirmLabel="Remove"
        destructive
        pending={remove.pending}
        onConfirm={() => void remove.run().catch(() => setConfirmRemove(false))}
      />
    </Card>
  )
}

function FieldInput({ id, field, value, disabled, onChange }: { id: string; field: Field; value: string | boolean | undefined; disabled: boolean; onChange: (value: string | boolean) => void }) {
  if (field.kind === 'checkbox') {
    return (
      <label className="flex items-center gap-2 self-end pb-2 text-sm">
        <Checkbox checked={value === true} disabled={disabled} onCheckedChange={(checked) => onChange(checked === true)} />
        {field.label}
      </label>
    )
  }
  const text = typeof value === 'string' ? value : ''
  return (
    <div className={field.kind === 'json' ? 'space-y-1.5 sm:col-span-2' : 'space-y-1.5'}>
      <Label htmlFor={id}>
        {field.label}
        {field.required && <span className="text-destructive"> *</span>}
      </Label>
      {field.kind === 'select' ? (
        <Select value={text} onValueChange={onChange} disabled={disabled}>
          <SelectTrigger id={id} className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {field.options?.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : field.kind === 'json' ? (
        <Textarea id={id} rows={7} className="font-mono text-xs" disabled={disabled} placeholder={field.placeholder} value={text} onChange={(event) => onChange(event.target.value)} />
      ) : (
        <Input
          id={id}
          inputMode={field.kind === 'number' ? 'numeric' : undefined}
          disabled={disabled}
          placeholder={field.placeholder}
          value={text}
          onChange={(event) => onChange(event.target.value)}
        />
      )}
      {field.help && <p className="text-muted-foreground text-xs">{field.help}</p>}
    </div>
  )
}

'use client'

import { useMemo, useState } from 'react'
import { RefreshCw, RotateCcw } from 'lucide-react'
import type { DeliveryStatus } from '@babulvaibhav/egradx-client'
import { useAction, useDeliveryLog } from '@babulvaibhav/egradx-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { EmptyState, ErrorState } from '../egradx-common'
import { channelLabel, errorText, formatRelative, ignoreNotice, tone, type Notify } from '../egradx-ui'

const PAGE_SIZE = 20
const ALL = 'all'
const STATUSES: DeliveryStatus[] = ['PENDING', 'SENT', 'DEAD']
const STATUS_TONE: Record<DeliveryStatus, string> = { SENT: tone.success, PENDING: tone.info, DEAD: tone.danger }

interface DeliveryLogProps {
  /** The channels to filter by. */
  channels: string[]
  /** Offers to send a dead delivery again. */
  canManage: boolean
  /** The platform's own deliveries (platform administrators). */
  platform?: boolean
  onNotify?: Notify
}

/** What was sent, newest first, with what happened to each: where a channel test's result shows up. */
export function DeliveryLog({ channels, canManage, platform, onNotify = ignoreNotice }: DeliveryLogProps) {
  const [channel, setChannel] = useState(ALL)
  const [status, setStatus] = useState(ALL)
  // A new filter goes back to the first page.
  const filter = useMemo(
    () => ({ channel: channel === ALL ? undefined : channel, status: status === ALL ? undefined : (status as DeliveryStatus) }),
    [channel, status],
  )
  const log = useDeliveryLog({ filter, pageSize: PAGE_SIZE, platform })
  const requeue = useAction(async (id: string) => {
    try {
      await log.requeue(id)
      onNotify({ tone: 'success', title: 'Queued for another try' })
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not requeue', description: errorText(error) })
    }
  })
  const pages = Math.max(1, Math.ceil(log.totalElements / PAGE_SIZE))

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        <Select value={channel} onValueChange={setChannel}>
          <SelectTrigger className="w-44" aria-label="Channel">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>All channels</SelectItem>
            {channels.map((id) => (
              <SelectItem key={id} value={id}>
                {channelLabel(id)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Select value={status} onValueChange={setStatus}>
          <SelectTrigger className="w-40" aria-label="Status">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>All statuses</SelectItem>
            {STATUSES.map((value) => (
              <SelectItem key={value} value={value}>
                {value}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button variant="outline" size="sm" onClick={() => void log.reload()} disabled={log.loading}>
          <RefreshCw /> Refresh
        </Button>
      </div>

      {log.loading && log.items.length === 0 ? (
        <Skeleton className="h-40 w-full" />
      ) : log.error ? (
        <ErrorState error={log.error} onRetry={() => void log.reload()} />
      ) : log.items.length === 0 ? (
        <EmptyState title="Nothing sent yet" description="Messages sent appear here, with what happened to each." />
      ) : (
        <>
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>When</TableHead>
                  <TableHead>Channel</TableHead>
                  <TableHead>Kind</TableHead>
                  <TableHead>To</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Attempts</TableHead>
                  <TableHead>Last error</TableHead>
                  {canManage && <TableHead />}
                </TableRow>
              </TableHeader>
              <TableBody>
                {log.items.map((delivery) => (
                  <TableRow key={delivery.id}>
                    <TableCell className="whitespace-nowrap">{formatRelative(delivery.createdAt)}</TableCell>
                    <TableCell>{channelLabel(delivery.channel)}</TableCell>
                    <TableCell className="font-mono text-xs">{delivery.notificationKey ?? '—'}</TableCell>
                    <TableCell className="max-w-48 truncate">{delivery.address}</TableCell>
                    <TableCell>
                      <Badge variant="outline" className={STATUS_TONE[delivery.status]}>
                        {delivery.status}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">{delivery.attempts}</TableCell>
                    <TableCell className="text-muted-foreground max-w-64 truncate text-xs" title={delivery.lastError ?? undefined}>
                      {delivery.lastError ?? ''}
                    </TableCell>
                    {canManage && (
                      <TableCell className="text-right">
                        {delivery.status === 'DEAD' && (
                          <Button size="sm" variant="ghost" onClick={() => void requeue.run(delivery.id)} disabled={requeue.pending}>
                            <RotateCcw /> Retry
                          </Button>
                        )}
                      </TableCell>
                    )}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          <div className="text-muted-foreground flex items-center justify-between text-sm">
            <span>
              {log.totalElements} deliver{log.totalElements === 1 ? 'y' : 'ies'}
            </span>
            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={() => log.setPage(log.page - 1)} disabled={log.page === 0 || log.loading}>
                Previous
              </Button>
              <span>
                Page {log.page + 1} of {pages}
              </span>
              <Button variant="outline" size="sm" onClick={() => log.setPage(log.page + 1)} disabled={log.page + 1 >= pages || log.loading}>
                Next
              </Button>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

'use client'

import { useNotificationChannels } from '@babulvaibhav/egradx-react'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { ErrorState } from '../egradx-common'
import { channelLabel, ignoreNotice, tone, type Notify } from '../egradx-ui'
import { ChannelCard } from './channel-card'
import { CHANNEL_SPECS } from './channel-forms'
import { DeliveryLog } from './delivery-log'

interface NotificationChannelsProps {
  /** May change settings and send tests (`egradx.notification.manage`); otherwise read-only. */
  canManage: boolean
  /** Prefilled as the email test's address: usually the person's own. */
  defaultTestAddress?: string
  /** The platform's own channels and deliveries (platform administrators). */
  platform?: boolean
  onNotify?: Notify
}

/**
 * How the organization sends outside the app (email, Slack, SMS, WhatsApp, and channels added by configuration), and
 * what it sent. Reading needs `egradx.notification.read`.
 */
export function NotificationChannels({ canManage, defaultTestAddress, platform, onNotify = ignoreNotice }: NotificationChannelsProps) {
  const channels = useNotificationChannels({ platform })
  const known = new Set(CHANNEL_SPECS.map((spec) => spec.id))
  const others = (channels.data ?? []).filter((status) => !known.has(status.channel))

  return (
    <Tabs defaultValue="channels">
      <TabsList>
        <TabsTrigger value="channels">Channels</TabsTrigger>
        <TabsTrigger value="log">Delivery log</TabsTrigger>
      </TabsList>
      <TabsContent value="channels" className="space-y-4 pt-2">
        {channels.loading ? (
          <Skeleton className="h-64 w-full" />
        ) : !channels.data ? (
          <ErrorState error={channels.error} onRetry={() => void channels.reload()} />
        ) : (
          <>
            {CHANNEL_SPECS.map((spec) => {
              const status = channels.data!.find((candidate) => candidate.channel === spec.id)
              return (
                <ChannelCard
                  // Starts again from what is stored whenever that changes.
                  key={`${spec.id}-${status?.configuration?.updatedAt ?? 'none'}`}
                  spec={spec}
                  status={status}
                  actions={channels}
                  canManage={canManage}
                  defaultTestAddress={defaultTestAddress}
                  onNotify={onNotify}
                />
              )
            })}
            {others.length > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle>Other channels</CardTitle>
                  <CardDescription>Configured through the API; shown here for their status.</CardDescription>
                </CardHeader>
                <CardContent>
                  <ul className="divide-y">
                    {others.map((status) => (
                      <li key={status.channel} className="flex items-center justify-between gap-2 py-2 text-sm">
                        <span>{channelLabel(status.channel)}</span>
                        <span className="text-muted-foreground flex items-center gap-2 text-xs">
                          {status.unavailableReason}
                          <Badge variant="outline" className={status.available ? tone.success : tone.warning}>
                            {status.available ? 'Available' : 'Unavailable'}
                          </Badge>
                        </span>
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            )}
          </>
        )}
      </TabsContent>
      <TabsContent value="log" className="pt-2">
        <DeliveryLog channels={(channels.data ?? []).map((status) => status.channel)} canManage={canManage} platform={platform} onNotify={onNotify} />
      </TabsContent>
    </Tabs>
  )
}
